class ListNode:
    def __init__(self, val, next=None):
        self.val = val
        self.next = next


def arr_to_list(arr):
    head = None
    tail = None
    for v in arr:
        node = ListNode(v)
        if not head:
            head, tail = node, node
        else:
            tail.next = node
            tail = node
    return head


def get_decimal_value(head_arr):
    head = arr_to_list(head_arr)
    result = 0
    node = head
    while node:
        result = result * 2 + node.val
        node = node.next
    return result

